contract InvMutTest {
    C c;
    address deployer;

    constructor(C _c) {
        c = _c;
        // record the deployer (owner) as the address that created C: it's c.owner() but owner is public
        deployer = c.owner();
    }

    // The test takes parameters to attempt withdraw by an arbitrary caller addrIsOwner flag,
    // an amount to withdraw, and some value to send to trigger fallback.
    // We cannot change msg.sender of this contract when calling c, so to simulate owner vs non-owner
    // we rely on the fact that this test contract is NOT the owner unless deployer == address(this).
    // The rule: if this contract is owner then withdraws must succeed and reduce c balance; otherwise they must revert and leave state unchanged.

    function run(bool pretendOwner, uint sendToFallback, uint withdrawAmount) public payable {
        require(true);

        // Ensure we have Ether to send to c to set up balance if requested
        if (sendToFallback > 0) {
            // require balance available in this contract to send
            require(address(this).balance >= sendToFallback);
            // send Ether to c to increase its balance and trigger fallback (increments depositsCount)
            c.f{value: sendToFallback}();
        }

        // Read observable before-values
        uint beforeBalance = address(c).balance;
        uint beforeDeposits = c.depositsCount();

        bool reverted;
        // Try withdraw call
        if (pretendOwner) {
            // If pretendOwner is true, require that this test contract actually is the owner; otherwise the call should revert and we will detect that.
            // We don't change msg.sender; this is only a selector for expected behavior.
            // Attempt withdraw and catch revert
            try c.withdraw(withdrawAmount) {
                reverted = false;
            } catch {
                reverted = true;
            }
        } else {
            // Expect non-owner path
            try c.withdraw(withdrawAmount) {
                reverted = false;
            } catch {
                reverted = true;
            }
        }

        // Read observable after-values
        uint afterBalance = address(c).balance;
        uint afterDeposits = c.depositsCount();

        // General rule assertion:
        // If this contract is owner (deployer == address(this)) then withdraw should not revert and contract balance should decrease by withdrawAmount (but not go below zero) — however withdraw uses transfer which will revert if insufficient funds, so we assert: if owner and withdraw did not revert then afterBalance + withdrawAmount == beforeBalance.
        // If this contract is not owner then withdraw must revert and neither balance nor depositsCount change.

        assert(
            (
                (deployer == address(this))
                ? (
                    // owner case: withdraw must not revert OR if it reverted it's allowed only when funds insufficient; we assert the invariant in the not-reverted case
                    (reverted == false && afterBalance + withdrawAmount == beforeBalance) || (reverted == true && afterBalance == beforeBalance && afterDeposits == beforeDeposits)
                  )
                : (
                    // non-owner: must revert and no state change
                    (reverted == true && afterBalance == beforeBalance && afterDeposits == beforeDeposits)
                  )
            )
        );
    }

    // Allow receiving Ether so this contract can fund calls
    receive() external payable {}
}

contract InvMutTest {
    C c;
    address deployer;

    constructor(C _c) {
        c = _c;
        deployer = c.owner();
    }

    // params: sendToFallback funds to send to c to create balance and trigger fallback;
    // withdrawAmount is the amount we attempt to withdraw.
    function run(uint sendToFallback, uint withdrawAmount) public payable {
        require(true);

        // If we will send Ether to c, ensure this contract has the funds available
        if (sendToFallback > 0) {
            require(address(this).balance >= sendToFallback);
            // call c's fallback by sending Ether with empty data
            (bool ok, ) = address(c).call{value: sendToFallback}("\x00");
            // fallback doesn't revert in C, but we don't require ok here; it's setup
            // (we allow ok being false but then balance won't increase)
        }

        uint beforeBalance = address(c).balance;
        uint beforeDeposits = c.depositsCount();

        bool reverted;
        try c.withdraw(withdrawAmount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint afterBalance = address(c).balance;
        uint afterDeposits = c.depositsCount();

        // Assertion as described in property_summary:
        // - If this contract is the owner, then a successful (non-reverting) withdraw must reduce c's balance by exactly withdrawAmount.
        //   If the withdraw reverted, state must be unchanged.
        // - If not owner, withdraw must revert and state must be unchanged.
        assert(
            (deployer == address(this))
            ? (
                // owner case
                (reverted == false && afterBalance + withdrawAmount == beforeBalance && afterDeposits == beforeDeposits)
                ||
                (reverted == true && afterBalance == beforeBalance && afterDeposits == beforeDeposits)
              )
            : (
                // non-owner: must revert and no changes
                (reverted == true && afterBalance == beforeBalance && afterDeposits == beforeDeposits)
              )
        );
    }

    // allow receiving Ether so this contract can be funded in the test environment
    receive() external payable {}
}

