        if (sendToFallback > 0) {
            require(address(this).balance >= sendToFallback);
            // call c's fallback by sending Ether with empty data using a low-level call to trigger fallback
            (bool _ok, ) = address(c).call{value: sendToFallback}("");
            // ignore _ok; fallback in C does not revert, but if the transfer failed balance won't increase
        }

        uint beforeBalance = address(c).balance;
        uint beforeDeposits = c.depositsCount();

        bool reverted;
        // top-level state-changing call: attempt withdraw
        try c.withdraw(withdrawAmount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint afterBalance = address(c).balance;
        uint afterDeposits = c.depositsCount();

