        // or it reverted and both balance and depositsCount are unchanged.
        // If not owner, withdraw must revert and balance and depositsCount unchanged.
        assert(
            (c.owner() == address(this))
            ? (
                (!reverted && afterBalance + withdrawAmount == beforeBalance && afterDeposits == beforeDeposits)
                ||
                (reverted && afterBalance == beforeBalance && afterDeposits == beforeDeposits)
              )
            : (reverted && afterBalance == beforeBalance && afterDeposits == beforeDeposits)
        );
    }

    receive() external payable {}
}

