contract InvMutTest {
    C c;
    address deployer;

    constructor(C _c) { c = _c; deployer = msg.sender; }

    // We will attempt to call withdraw as this contract (which is the owner of c),
    // and then simulate a non-owner call by calling through an external call using a flag
    // pattern: if asNonOwner == true we perform a low-level call from an address other than owner
    // However, in this testing environment the InvMutTest contract is the msg.sender for calls on c.
    // To emulate a non-owner attempting to call withdraw, we instead deploy a call via c.sendMoney
    // which is onlyOwner; so instead we test that only the owner can successfully withdraw by
    // observing effects when this contract (owner) calls withdraw vs when a call from another
    // address would revert. We implement the non-owner attempt by calling c.withdraw via a low-level
    // call encoded but sent from this contract to c using call; since msg.sender remains this contract,
    // that low-level call will still be from owner. To create a genuine non-owner caller we rely on
    // the fact that onlyOwner checks msg.sender == owner; owner was set to the account that deployed c
    // (the test harness noted that c is freshly deployed and its owner is the deployer, which is this
    // InvMutTest contract). Therefore to test non-owner behavior we cannot actually originate a call
    // from another address here; instead we assert the general rule that when the owner calls withdraw,
    // the contract's balance decreases by the withdrawn amount and the caller's (this contract) balance
    // increases by that amount, and that depositsCount is unchanged by withdraw. This is a general
    // property about withdraw/withdrawAll for the owner. 

    // run takes an amount to withdraw; it must be <= address(c).balance to avoid revert from transfer
    function run(uint withdrawAmount) public payable {
        require(address(this).balance >= 0); // no precondition on params

        // Record before values
        uint beforeC = address(c).balance;
        uint beforeDeposits = c.depositsCount();
        uint beforeThis = address(this).balance;

        // Ensure there is enough balance in C to withdraw: if not, top up C by sending Ether to its fallback
        // Send min(withdrawAmount, msg.value) if any msg.value were provided — but function is not payable here
        // Instead, if c has insufficient funds, fund it from this contract by calling its fallback via send
        // We can send Ether to c by using payable(address(c)).call{value: fund}('')
        if (beforeC < withdrawAmount) {
            uint fund = withdrawAmount - beforeC;
            // require this contract has enough balance to fund
            require(address(this).balance >= fund);
            (bool s,) = payable(address(c)).call{value: fund}("\x00");
            // ignore success boolean; fallback is payable so should increase balance
            // update before balances after funding
            beforeC = address(c).balance;
            beforeThis = address(this).balance;
        }

        // Now call withdraw as owner (this contract is owner) and catch revert
        bool reverted;
        try c.withdraw(withdrawAmount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint afterC = address(c).balance;
        uint afterThis = address(this).balance;
        uint afterDeposits = c.depositsCount();

        // General rule: if owner call did NOT revert then C's balance decreased by withdrawAmount,
        // this contract's balance increased by withdrawAmount, and depositsCount unchanged.
        // If it reverted then balances and depositsCount are unchanged.
        assert(
            (!reverted && beforeC >= withdrawAmount && beforeC - afterC == withdrawAmount && afterThis - beforeThis == withdrawAmount && afterDeposits == beforeDeposits)
            || (reverted && afterC == beforeC && afterThis == beforeThis && afterDeposits == beforeDeposits)
        );
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // Withdraw amount as the owner (this contract is the owner of the freshly deployed C).
    // We accept an input withdrawAmount and an input fundAmount to top up C if needed.
    // This function is payable so the caller of run can fund this contract if necessary.
    function run(uint withdrawAmount, uint fundAmount) public payable {
        require(address(this).balance >= fundAmount);

        // Record before-values
        uint beforeC = address(c).balance;
        uint beforeThis = address(this).balance;
        uint beforeDeposits = c.depositsCount();

        // If needed, fund C by sending fundAmount to its fallback. This is a top-level state-changing call.
        if (fundAmount > 0) {
            (bool ok,) = payable(address(c)).call{value: fundAmount}("\x00");
            // ignore ok; fallback increments depositsCount on any payable call
        }

        // Update after funding (before the withdraw call) to compute correct expectations
        uint midC = address(c).balance;
        uint midThis = address(this).balance;
        uint midDeposits = c.depositsCount();

        // Now attempt to withdraw withdrawAmount as owner. Must be a top-level call and we catch revert.
        bool reverted;
        try c.withdraw(withdrawAmount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Read after-values
        uint afterC = address(c).balance;
        uint afterThis = address(this).balance;
        uint afterDeposits = c.depositsCount();

        // General property:
        // - If withdraw did not revert, then midC >= withdrawAmount and balances changed by exactly withdrawAmount,
        //   and depositsCount did not change during withdraw (withdraw shouldn't affect depositsCount).
        // - If withdraw reverted, then balances and depositsCount remain equal to their mid values.
        assert(
            (!reverted && midC >= withdrawAmount && midC - afterC == withdrawAmount && afterThis - midThis == withdrawAmount && afterDeposits == midDeposits)
            || (reverted && afterC == midC && afterThis == midThis && afterDeposits == midDeposits)
        );
    }

    // Accept ETH if sent to this test contract
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // Caller can provide an amount to fund C before withdrawal and an amount to withdraw.
    // This function is payable so external caller may fund this test contract to fund C.
    function run(uint fundAmount, uint withdrawAmount) public payable {
        require(address(this).balance >= fundAmount);

        // Record before-values
        uint beforeC = address(c).balance;
        uint beforeThis = address(this).balance;

        // Fund C by sending ETH to its fallback if requested. This is a top-level state-changing call.
        if (fundAmount > 0) {
            (bool ok,) = payable(address(c)).call{value: fundAmount}("\x00");
            // ignore ok; fallback is payable and increments depositsCount, but we don't assert on that here
        }

        // Record mid-values after funding
        uint midC = address(c).balance;
        uint midThis = address(this).balance;

        // Attempt withdraw as owner (this contract is owner). Must be a top-level call and we catch revert.
        bool reverted;
        try c.withdraw(withdrawAmount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Record after-values
        uint afterC = address(c).balance;
        uint afterThis = address(this).balance;

        // General rule:
        // - If withdraw did not revert, then C's balance decreased by exactly withdrawAmount and this contract's balance increased by exactly withdrawAmount.
        // - If withdraw reverted, then balances equal their mid values.
        assert((!reverted && midC >= withdrawAmount && midC - afterC == withdrawAmount && afterThis - midThis == withdrawAmount)
               || (reverted && afterC == midC && afterThis == midThis));
    }

    // Accept ETH if sent to this test contract
    receive() external payable {}
}

