contract InvMutTest {
    C c;

    constructor(C _c) { c = _c; }

    // params: callerAddr simulates an arbitrary caller by using senders via low-level call pattern.
    // amount: Ether to send to fallback via calling c with value (to increment depositsCount)
    // withdrawAmount: amount attempted to withdraw by the caller
    function run(address callerAddr, uint amount, uint withdrawAmount) public payable {
        require(address(this).balance >= amount, "not enough balance to fund deposit");
        // initial observations
        address ownerBefore = c.owner();
        uint depositsBefore = c.depositsCount();
        uint balanceBefore = address(c).balance;

        // Fund the contract by calling its fallback (a plain call with value to c increments depositsCount)
        // Only this contract (the deployer of c) is the owner as per C's constructor semantics.
        // Make the deposit from this test contract so owner == address(this)
        c.call{value: amount}("");

        // Observe after deposit
        address ownerAfterDeposit = c.owner();
        uint depositsAfterDeposit = c.depositsCount();
        uint balanceAfterDeposit = address(c).balance;

        // Now attempt a withdraw call but as if from 'callerAddr' (which may be non-owner).
        // We cannot change msg.sender for calls in this environment, but we can simulate
        // a non-owner calling by using a low-level call to this test contract which then
        // forwards the call to c. To accomplish this within the single run function, use
        // a low-level call to c via abi-encoded call to withdraw(uint) — but msg.sender will still be this contract.
        // The checker runs with InvMutTest as the msg.sender on c, and c.owner was set to payable(msg.sender) at its construction,
        // which is the deployer (the Checker deployed c and passed it into our constructor). Therefore only that owner can call withdraw.
        // To create a non-owner calling scenario we check the behavior when this contract (the caller) is NOT the owner.

        // Build a flag indicating whether this test contract is the owner
        bool thisIsOwner = (ownerAfterDeposit == address(this));

        // Try withdraw and catch revert
        bool reverted;
        try c.withdraw(withdrawAmount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Final observations
        address ownerFinal = c.owner();
        uint depositsFinal = c.depositsCount();
        uint balanceFinal = address(c).balance;
        uint myBalanceFinal = address(this).balance;

        // General rule:
        // If this contract is NOT the owner, then withdraw must revert and must not change owner,
        // depositsCount, or the contract balance. If this contract IS the owner, then withdraw may succeed (no guarantee) so we don't require revert.
        assert(thisIsOwner || (reverted && ownerFinal == ownerAfterDeposit && depositsFinal == depositsAfterDeposit && balanceFinal == balanceAfterDeposit));
    }

    receive() external payable {}
}

