contract InvMutTest {
    C c;

    constructor(C _c) { c = _c; }

    // params:
    // depositAmount: Ether to send to c (to possibly change depositsCount and balance)
    // withdrawAmount: amount to attempt to withdraw as non-owner
    function run(uint depositAmount, uint withdrawAmount) public payable {
        require(address(this).balance >= depositAmount);

        // Record state before deposit
        address ownerBefore = c.owner();
        uint depositsBefore = c.depositsCount();
        uint balanceBefore = address(c).balance;

        // Make a plain top-level state-changing call to c by sending Ether to trigger fallback
        (bool sent, ) = address(c).call{value: depositAmount}("\x00");
        // Note: sent may be true/false but the fallback increments depositsCount only on successful fallback execution

        // Observe state immediately after deposit attempt
        address ownerAfterDeposit = c.owner();
