    // amount is the ETH to send along with the call when InvMutTest invokes fallback (deposits)
    // callValue is the value attempted to withdraw/sendMoney by the caller (onlyOwner functions)
    // useSendMoney toggles whether to call sendMoney (true) or withdraw (false)
