                  )
                : (
                    // Non-owner: privileged calls must not succeed in changing balance; either they reverted or left balance unchanged
                    (reverted && afterBalance == beforeBalance)
                  )
            )
        );
    }

    // allow receiving Ether from c.withdraw
    receive() external payable {}
}

contract InvMutTest {
