    constructor(C _c) { c = _c; }

    // callerIsOwner: if true, perform an owner call (this contract is owner); if false, attempt privileged calls and expect revert
    // depositAmount: amount of wei to send to C to trigger its fallback (increments depositsCount)
    // callValue: value passed to withdraw/sendMoney
    // target and data: parameters for sendMoney when owner calls
    function run(bool callerIsOwner, uint depositAmount, uint callValue, address target, bytes calldata data) public payable {
        require(address(this).balance >= depositAmount, "insufficient test balance for deposit");

        // 1) Fund C by sending Ether which triggers fallback and increments depositsCount
        // We must send Ether by calling address(c).call{value: ...}("") because fallback is payable
        (bool sent,) = address(c).call{value: depositAmount}("");
        require(sent, "deposit failed");

        uint beforeBalance = address(c).balance;
        uint beforeDeposits = c.depositsCount();

        bool anyReverted = false;

        if (callerIsOwner) {
            // Owner path: call either withdraw or sendMoney based on whether target is zero address
            // If target == address(0), call withdraw to transfer to owner (this contract)
            if (target == address(0)) {
                // withdraw transfers funds to owner (this contract)
                c.withdraw(callValue);
            } else {
                // sendMoney attempts to forward funds to target
                c.sendMoney(target, callValue, data);
            }
        } else {
            // Non-owner: attempts should revert. We try both privileged functions and record if they revert.
            try c.withdraw(callValue) {
                // unexpected success
                anyReverted = false;
            } catch {
                anyReverted = true;
            }
            // try sendMoney as well and combine: require at least one revert; conservative: require both revert
            bool sendReverted = false;
            try c.sendMoney(target, callValue, data) {
                sendReverted = false;
            } catch {
                sendReverted = true;
            }
            // non-owner expectation: both privileged calls revert
            anyReverted = anyReverted && sendReverted;
        }

        uint afterBalance = address(c).balance;
        uint afterDeposits = c.depositsCount();

        // Assert general rule:
        // - depositsCount never decreases
        // - If callerIsOwner: C's balance does not increase due to the privileged call (owner only withdraw/sendMoney cannot raise C balance)
        // - If not owner: both privileged calls reverted and C's balance unchanged
        assert(
            afterDeposits >= beforeDeposits
            && (
                callerIsOwner
                ? (afterBalance <= beforeBalance)
                : (anyReverted && afterBalance == beforeBalance)
            )
        );
    }

    // allow receiving Ether from C.withdraw
    receive() external payable {}
}

