contract InvMutTest {
    C c;
    address deployer;

    constructor(C _c) { c = _c; deployer = address(this); }

    // param: whether the call should be made as owner (true) or as attacker (false)
    // param: amount of wei to send when invoking fallback (to increase depositsCount)
    // param: withdrawAmount to attempt withdrawing
    function run(bool asOwner, uint fallbackAmount, uint withdrawAmount) public payable {
        require(address(this).balance >= fallbackAmount, "insufficient balance for fallback send");

        // initial observations
        uint beforeDeposits = c.depositsCount();
        uint beforeBalance = address(c).balance;

        // Make the contract receive Ether by calling its fallback (increment depositsCount)
        // Only send Ether if fallbackAmount > 0
        if (fallbackAmount > 0) {
            // call fallback by sending plain Ether
            (bool ok,) = address(c).call{value: fallbackAmount}("");
            // we don't assert success here; fallback is payable so it should succeed
            // but we still continue regardless of ok to let property capture behavior
            (ok); // silence unused warning
        }

        // attempt to withdraw from c either as owner (this contract) or as a simulated attacker
        // To simulate attacker we use a low-level call from this contract but change msg.sender is impossible;
        // Instead, we simulate non-owner by deploying a proxy that forwards calls — but per constraints we cannot deploy.
        // Instead, we encode behavior: if asOwner==true we call withdraw, otherwise we call via try/catch from outside which will still have msg.sender == this,
        // so to create a non-owner call we instead call c.withdraw via a call from an externally controlled account is impossible here.
        // However, the property we assert will be formulated to reflect actual capabilities: when called by owner (this contract), withdraw should not revert and should decrease c.balance by withdrawAmount (capped by balance);
        // and when called by non-owner (simulated by we expect revert) the call should revert and not change depositsCount nor balance.

        bool didRevert;
        // Only two possible calls are allowed by contract: withdraw and withdrawAll. We attempt withdraw with withdrawAmount.
        if (asOwner) {
            // call as owner (this contract is owner) - should succeed (not revert)
            try c.withdraw(withdrawAmount) {
                didRevert = false;
            } catch {
                didRevert = true;
            }
        } else {
            // To simulate a non-owner attempt, we invoke c.withdraw via low-level call with encoded selector but msg.sender will still be this contract.
            // We instead call the function sendMoney to make the contract call itself from within, but sendMoney has onlyOwner too.
            // Given constraints we cannot change msg.sender here; however we can still test this invariant:
            // If a call reverts when invoked (didRevert==true), then depositsCount and balance must be unchanged from before the attempted call that reverts.
            // So we attempt to call a function that may revert: call withdraw with huge value to possibly cause revert? withdraw uses transfer which can revert if transfer fails, but owner check comes first.
            // We'll attempt to call withdraw and capture revert flag; in practice this will not revert when asOwner==false because msg.sender is owner.
            try c.withdraw(withdrawAmount) {
                didRevert = false;
            } catch {
                didRevert = true;
            }
        }

        uint afterDeposits = c.depositsCount();
        uint afterBalance = address(c).balance;

        // If the withdraw call reverted, then depositsCount and balance must be unchanged from before the attempted withdraw call.
        // If it did not revert and the caller is owner, then the decrease in c.balance must be <= withdrawAmount and <= beforeBalance.
        // We express both in one assert:
        if (didRevert) {
            assert(afterDeposits == beforeDeposits && afterBalance == beforeBalance);
        } else {
            // successful withdraw: balance decreased by some amount delta where 0 <= delta <= withdrawAmount and delta <= beforeBalance
            uint delta;
            if (afterBalance <= beforeBalance) {
                delta = beforeBalance - afterBalance;
            } else {
                // balance increased instead (shouldn't happen on successful withdraw), treat as violation
                delta = 0;
            }
            assert(delta <= withdrawAmount && delta <= beforeBalance);
        }
    }

    // allow receiving Ether for setup
    receive() external payable {}
}

