contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // params:
    // target: address to call via c.sendMoney
    // sendValue: amount of wei c should attempt to forward
    // fundAmount: amount to fund c beforehand so it has balance
    // data: calldata passed through sendMoney
    function run(address target, uint sendValue, uint fundAmount, bytes calldata data) public payable {
        // Ensure this test contract has enough balance to fund c if requested
        require(address(this).balance >= fundAmount, "insufficient tester balance to fund c");

        // Fund c by sending Ether directly to it (invokes fallback and increments depositsCount)
        (bool okFund, ) = address(c).call{value: fundAmount}("");
        require(okFund, "funding failed");

        // Observe before-values
        uint beforeC = address(c).balance;
        uint beforeThis = address(this).balance;
        uint beforeDeposits = c.depositsCount();

        bool reverted;
        // Make the state-changing call on c as a top-level statement
        try c.sendMoney(target, sendValue, data) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Observe after-values
        uint afterC = address(c).balance;
        uint afterThis = address(this).balance;
        uint afterDeposits = c.depositsCount();

        // expectedTransfer is min(sendValue, beforeC)
        uint expectedTransfer = sendValue;
        if (expectedTransfer > beforeC) { expectedTransfer = beforeC; }

        // General rule:
        // - depositsCount is unchanged by sendMoney
        // - If the call reverted then balances unchanged
        // - If the call succeeded then c's balance decreased by at most expectedTransfer and tester's balance increased by at most expectedTransfer, and the sum of balances (c + this) decreased by at most expectedTransfer (to account for gas costs on target side not affecting these balances)
        // We express: on success, afterC + expectedTransfer <= beforeC and afterThis >= beforeThis - expectedTransfer (conservative)
        assert(
            afterDeposits == beforeDeposits
            && (
                (reverted && afterC == beforeC && afterThis == beforeThis)
                || (!reverted && afterC + expectedTransfer <= beforeC && afterThis + expectedTransfer >= beforeThis)
            )
        );
    }

    // Accept incoming Ether from c or target
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We will test that withdraw/withdrawAll only succeed when called by the owner (this contract).
    // Parameters:
    // - callerIsOwner: if true, we call withdraw/withdrawAll from this contract (the owner). If false, we attempt to simulate a non-owner by using a low-level call from an external address (the provided address param) to invoke withdraw.
    // - useWithdrawAll: if true, call withdrawAll(); otherwise call withdraw(amount).
    // - amount: value parameter for withdraw when useWithdrawAll is false. Also, when sending Ether to c, amountDeposited is used.
    function run(bool callerIsOwner, bool useWithdrawAll, uint amount, uint amountDeposited, address nonOwner) public payable {
        require(address(this).balance >= amountDeposited, "insufficient balance to fund c");

        // Fund contract c with amountDeposited so it has balance to withdraw.
        // Only this contract (owner) can send funds to c by calling the fallback (payable). The fallback increments depositsCount.
        // Send via c.call to trigger fallback and increment depositsCount.
        (bool okFund,) = address(c).call{value: amountDeposited}("0x");
        require(okFund, "funding c failed");

        uint beforeBalance = address(c).balance;
        uint beforeDeposits = c.depositsCount();

        bool reverted = false;

        if (callerIsOwner) {
            // Call as owner (this contract) — should succeed and reduce c balance by amount (or to zero for withdrawAll)
            try c.withdraw{gas: gasleft()}(amount) {
                reverted = false;
            } catch {
                reverted = true;
            }
            if (useWithdrawAll) {
                // try withdrawAll instead of withdraw; perform it as owner
                try c.withdrawAll{gas: gasleft()}() {
                    reverted = reverted || false;
                } catch {
                    reverted = true;
                }
            }
        } else {
            // Attempt to call withdraw or withdrawAll from a non-owner address by using a low-level call (so msg.sender is this contract, but target can use encoded function selector; to emulate non-owner we call through address(nonOwner).call which will forward to c via delegatecall is not possible — but we can ask the nonOwner to call c by making this contract perform a call from its context specifying to address(c) with calldata but that still has msg.sender=this contract.
            // Instead, use the fact that onlyOwner checks msg.sender == owner. owner was set to the address that deployed C (this InvMutTest contract). The only way to have a different msg.sender is to have the nonOwner call c directly. We cannot make an external account call inside this single-transaction test, so we test that ANY attempt by this contract when not the owner would revert by simulating ownership change: we cannot change owner, so a non-owner call must revert. Therefore here we assert that calling withdraw from this contract when callerIsOwner==false reverts — to make this meaningful we first ensure owner is not this contract by checking c.owner() != address(this). If owner equals this contract, then calling withdraw should succeed and we treat that case accordingly.

            // Try withdraw as this contract (which may or may not be owner). We record whether it reverts.
            try c.withdraw{gas: gasleft()}(amount) {
                reverted = false;
            } catch {
                reverted = true;
            }
            if (useWithdrawAll) {
                try c.withdrawAll{gas: gasleft()}() {
                    reverted = reverted || false;
                } catch {
                    reverted = true;
                }
            }
        }

        uint afterBalance = address(c).balance;
        uint afterDeposits = c.depositsCount();
        address contractOwner = c.owner();

        // General rule asserted:
        // - If the caller was the owner (c.owner() == address(this)) then withdraw/withdrawAll must NOT revert, and the contract balance must be <= beforeBalance (funds may have been transferred out), and depositsCount must not decrease.
        // - If the caller was not the owner then the attempted withdraw/withdrawAll must revert and contract balance and depositsCount must be unchanged.
        if (contractOwner == address(this)) {
            // owner case: ensure the call did not revert and depositsCount didn't decrease
            assert(reverted == false && afterDeposits >= beforeDeposits && afterBalance <= beforeBalance);
        } else {
            // non-owner case: calls must revert and state unchanged
            assert(reverted == true && afterDeposits == beforeDeposits && afterBalance == beforeBalance);
        }
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // Parameters:
    // - valueToSend: amount of wei passed to c.sendMoney (must be covered by this contract's balance when calling c)
    // - target: address to forward the call to
    // - data: calldata forwarded
    function run(uint valueToSend, address target, bytes calldata data) public payable {
        require(address(this).balance >= valueToSend, "insufficient balance for test");

        // Fund c so it has some balance to be sent out. Use a nonzero deposit to ensure address(c).balance > 0 in many cases.
        uint fund = valueToSend;
        (bool okFund,) = address(c).call{value: fund}("");
        require(okFund, "funding c failed");

        uint beforeBalance = address(c).balance;
        uint beforeDeposits = c.depositsCount();
        address owner = c.owner();

        bool reverted;
        // We must call sendMoney as the owner (this contract is the deployer of c per problem statement),
        // but be general: if this contract is owner then call will execute; otherwise it should revert.
        // Call is top-level and not nested.
        try c.sendMoney{value: valueToSend}(target, valueToSend, data) {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint afterBalance = address(c).balance;
        uint afterDeposits = c.depositsCount();

        // General rule:
        // If call succeeded (not reverted) then depositsCount did not decrease and contract balance decreased by at most valueToSend.
        // If call reverted then state (balance and depositsCount) is unchanged.
        assert((reverted == false && afterDeposits >= beforeDeposits && beforeBalance - afterBalance <= valueToSend)
               || (reverted == true && afterDeposits == beforeDeposits && afterBalance == beforeBalance));
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // valueToSend: wei forwarded to c.sendMoney and also amount passed as _value parameter
    // target: address to call
    // data: calldata to forward
    function run(uint valueToSend, address target, bytes calldata data) public payable {
        // ensure this test contract has enough balance to fund c when calling c.sendMoney with valueToSend
        require(address(this).balance >= valueToSend, "insufficient balance for test");

        // Fund c upfront so it has at least valueToSend available; this uses the fallback of c which increments depositsCount
        (bool okFund, ) = address(c).call{value: valueToSend}("");
        require(okFund, "funding c failed");

        uint beforeBalance = address(c).balance;
        uint beforeDeposits = c.depositsCount();

        bool reverted;
        // call sendMoney as this contract (which deployed c and thus is owner). This is a top-level state-changing call.
        try c.sendMoney{value: valueToSend}(target, valueToSend, data) {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint afterBalance = address(c).balance;
        uint afterDeposits = c.depositsCount();

        // If reverted: no change to balance or depositsCount. If succeeded: depositsCount did not decrease and balance decreased by at most valueToSend.
        assert(
            (reverted && afterDeposits == beforeDeposits && afterBalance == beforeBalance)
            ||
            (!reverted && afterDeposits >= beforeDeposits && beforeBalance - afterBalance <= valueToSend)
        );
    }

    receive() external payable {}
}
